function longestClimb(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const climb = (r: number, c: number): number => {
    let best = 1;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] > grid[r][c]) best = Math.max(best, 1 + climb(nr, nc));
    }
    return best;
  };
  let ans = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) ans = Math.max(ans, climb(r, c));
  return ans;
}

