    if (best[r][c]) return best[r][c];
    let len = 1;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] > grid[r][c]) len = Math.max(len, 1 + dfs(nr, nc));
    }
    return (best[r][c] = len);
  };
  let ans = 0;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) ans = Math.max(ans, dfs(r, c));
  return ans;
}

