function longestClimb(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const cells: number[] = [];
  for (let i = 0; i < R * C; i++) cells.push(i);
  cells.sort((a, b) => grid[Math.floor(b / C)][b % C] - grid[Math.floor(a / C)][a % C]); // highest first
  const best: number[][] = Array.from({ length: R }, () => new Array(C).fill(1));
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let ans = 1;
  for (const id of cells) {
    const r = Math.floor(id / C), c = id % C;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && grid[nr][nc] > grid[r][c])
        best[r][c] = Math.max(best[r][c], 1 + best[nr][nc]); // higher neighbour is already final
    }
    ans = Math.max(ans, best[r][c]);
  }
  return ans;
}

